(function(root,factory){const api=factory();if(typeof module==='object')module.exports=api;else root.MaterialCompiler=api;})(typeof window==='undefined'?globalThis:window,function(){
const names={evidence:'行动与依据',roi:'收益算盘',pair:'概念配对',match:'答案配对',cloze:'书页填空',classify:'证据分拣',deliver:'角色投递',order:'流程装配',multi:'多项收集',sort:'分类投递',scenario:'情境委托',numeric:'钟表账本'};
const text=x=>(typeof x==='string'||typeof x==='number'?String(x):'').replace(/\u0000/g,'').trim().slice(0,1500);
function metadata(raw){raw=raw&&typeof raw==='object'&&!Array.isArray(raw)?raw:{};const m={};const steps=raw.steps??raw['步骤'];if(Array.isArray(steps)&&steps.length>=2&&steps.length<=8){const list=steps.map(text).filter(Boolean);if(list.length>=2&&new Set(list).size===list.length)m.steps=list;}const answers=raw.answers??raw.correctAnswers??(Array.isArray(raw.answer)?raw.answer:null);if(Array.isArray(answers))m.answers=[...new Set(answers.map(text).filter(Boolean))].slice(0,10);if(raw.options&&Array.isArray(raw.options)){const a=raw.options.filter(x=>x&&typeof x==='object'&&x.correct===true).map(x=>text(x.text)).filter(Boolean);if(a.length>1)m.answers=[...new Set(a)];}
const categories=raw.categories??raw['分类'];if(Array.isArray(categories)&&categories.length>=2&&categories.length<=4){const list=categories.map(c=>({label:text(c.label??c.name),items:Array.isArray(c.items)?c.items.map(text).filter(Boolean).slice(0,6):[]})).filter(c=>c.label&&c.items.length);if(list.length>=2&&new Set(list.map(x=>x.label)).size===list.length&&new Set(list.flatMap(x=>x.items)).size===list.flatMap(x=>x.items).length)m.categories=list;}
const pairs=raw.pairs??raw['配对'];if(Array.isArray(pairs)&&pairs.length>=2&&pairs.length<=6){const list=pairs.map(p=>({left:text(p?.left),right:text(p?.right)})).filter(p=>p.left&&p.right);if(list.length===pairs.length&&new Set(list.map(p=>p.left)).size===list.length&&new Set(list.map(p=>p.right)).size===list.length)m.pairs=list;}
if(typeof raw.context==='string')m.context=raw.context.slice(0,1500);const blank=raw.blank??raw.template;if(typeof blank==='string'&&blank.includes('___'))m.blank=blank.slice(0,1500);
const calc=raw.calculation;if(calc&&calc.operation==='net-time'&&['before','after','review'].every(k=>Number.isFinite(calc[k])&&calc[k]>=0&&calc[k]<=100000)){m.calculation={operation:'net-time',before:calc.before,after:calc.after,review:calc.review,unit:text(calc.unit)||'分钟'};}
if(calc&&calc.operation==='roi'&&Number.isFinite(calc.costs)&&calc.costs>0&&calc.costs<=1e9&&Number.isFinite(calc.benefits)&&calc.benefits>=0&&calc.benefits<=1e9)m.calculation={operation:'roi',costs:calc.costs,benefits:calc.benefits,unit:'%'};
const mode=text(raw.mode??raw.kind??raw.mechanic);if(Object.hasOwn(names,mode))m.mode=mode;return m;}
function available(c){const out=['match','classify','deliver'];const quote=text(c.quote);if(c.blank||(text(c.a).length<=24&&quote.includes(c.a)))out.push('cloze');if(Array.isArray(c.steps)&&c.steps.length>=2)out.push('order');if(Array.isArray(c.answers)&&c.answers.length>=2)out.push('multi');if(Array.isArray(c.categories)&&c.categories.length>=2)out.push('sort');if(c.pairs?.length>=2)out.push('pair');if(c.context)out.push('scenario');if(c.answers?.length===2)out.push('evidence');if(c.calculation)out.push(c.calculation.operation==='roi'?'roi':'numeric');return out;}
function choose(c,index=0){const a=available(c);if(c.mode&&a.includes(c.mode))return c.mode;for(const preferred of ['order','multi','sort','pair','numeric','scenario'])if(a.includes(preferred))return preferred;return a[index%a.length];}
function compile(c,index=0,others=[]){const mode=choose(c,index),base={id:c.id,mode,name:names[mode],question:c.q,quote:c.quote,source:c.source,locator:c.locator,topic:c.topic,answer:c.a};const wrong=[...new Set(c.wrong||[])].filter(x=>x&&x!==c.a).slice(0,4);
if(mode==='evidence')return{...base,station:'sorter',prompt:c.context||c.q,categories:['合适的行动','支持行动的依据'],pieces:[...c.answers.map((x,i)=>({text:x,key:'evidence-'+i,category:i,correct:true})),...wrong.map((x,i)=>({text:x,key:'unfounded-'+i,correct:false}))],target:2};
if(mode==='roi'){const p=c.calculation;return{...base,station:'ledger',prompt:'找到成本与收益账页，放入账本，再亲自计算 ROI。可以输入负数；百分号无需填写。',expected:Math.round((p.benefits-p.costs)/p.costs*10000)/100,calculation:p,pieces:[{text:'完整成本：'+p.costs+' 万元',key:'roi-cost',correct:true},{text:'同期间收益：'+p.benefits+' 万元',key:'roi-benefit',correct:true}],target:2};}
if(mode==='pair')return{...base,station:'book',prompt:'把找到的解释或用途，配到对应概念卡上。每个概念对应一份材料。',categories:c.pairs.map(p=>p.left),pieces:c.pairs.map((p,i)=>({text:p.right,key:'pair-'+i,category:i,correct:true})),target:c.pairs.length};
if(mode==='order')return{...base,station:'machine',prompt:'按材料中的真实先后顺序，把步骤齿轮装入机器。',pieces:c.steps.map((s,i)=>({text:s,key:'step-'+i,correct:true,order:i})),target:c.steps.length};
if(mode==='multi'){const answers=[...c.answers];return{...base,station:'sorter',prompt:`找出 ${answers.length} 份符合问题的卷轴，放进可信材料框后核验。`,pieces:[...answers.map((s,i)=>({text:s,key:'yes-'+i,correct:true})),...wrong.filter(x=>!answers.includes(x)).slice(0,Math.max(2,answers.length)).map((s,i)=>({text:s,key:'no-'+i,correct:false}))],target:answers.length};}
if(mode==='sort'){const pieces=c.categories.flatMap((g,i)=>g.items.map((s,j)=>({text:s,key:`cat-${i}-${j}`,category:i,correct:true})));return{...base,station:'sorter',prompt:'把每条材料投递到正确的分类站点。',categories:c.categories.map(x=>x.label),pieces,target:pieces.length};}
if(mode==='numeric'){const p=c.calculation,net=p.before-p.after-p.review,ans=String(net)+' '+p.unit;return{...base,station:'ledger',prompt:`使用前 ${p.before}${p.unit}，生成耗时 ${p.after}${p.unit}，复核耗时 ${p.review}${p.unit}。净节省多少？`,calculation:p,expected:net,pieces:[{text:ans,key:'net',correct:true},...[...new Set([p.before-p.after,p.after+p.review,net+5,net-5])].filter(n=>n!==net).slice(0,2).map((n,i)=>({text:String(n)+' '+p.unit,key:'numeric-wrong-'+i,correct:false}))],target:1};}
if(mode==='cloze'){const sentence=c.blank||text(c.quote).replace(c.a,'___');return{...base,station:'book',prompt:sentence,pieces:[{text:c.a,key:'answer',correct:true},...wrong.slice(0,2).map((s,i)=>({text:s,key:'wrong-'+i,correct:false}))],target:1};}
if(mode==='scenario')return{...base,station:'mailbox',prompt:c.context+'\n'+c.q,pieces:[{text:c.a,key:'answer',correct:true},...wrong.slice(0,2).map((s,i)=>({text:s,key:'wrong-'+i,correct:false}))],target:1};
return{...base,station:mode==='deliver'?'mailbox':mode==='classify'?'sorter':'book',prompt:c.q,pieces:[{text:c.a,key:'answer',correct:true},...wrong.slice(0,2).map((s,i)=>({text:s,key:'wrong-'+i,correct:false}))],target:1};}
function preview(c){const capable=available(c);return{selected:choose(c),label:names[choose(c)],available:capable.map(id=>({id,label:names[id]})),warnings:[c.calculation?.operation==='net-time'&&text(c.a).replace(/\s/g,'')!==String(c.calculation.before-c.calculation.after-c.calculation.review)+c.calculation.unit?'计算结构与答案不一致，请先核对净节省数值和单位。':null,!c.wrong?.length&&!['order','sort','pair','evidence','roi','numeric'].includes(choose(c))?'未提供干扰项：这道题只使用已确认的有效材料，不把其他题的答案强行标成错误。':null,!c.quote?'缺少原文片段，请核对依据。':null,c.mode&&!capable.includes(c.mode)?'请求的玩法缺少必要结构，已回退到可执行玩法。':null].filter(Boolean)};}
return{names,metadata,available,choose,compile,preview};
});
